-- Requires variation_axes, muscle_tags, and equipment_tag columns (exercise tag migration).
begin;

insert into private.exercise_catalog_v1_archive(exercise_id, original_row)
select e.id, to_jsonb(e) from public.exercises e
where e.owner_id is null and e.source_sheet is distinct from 'Упражнения (Ноги) список'
on conflict (exercise_id) do nothing;

