insert into public.exercises
  (canonical_key, name, muscle_group, exercise_type, movement_type,
   equipment, source_sheet, source_row, status, variation_axes, muscle_tags, equipment_tag, description)
select 'rebuild_legs_' || source_row::text, name, 'Ноги', 'Силовое', 'Силовое',
       equipment, 'Упражнения (Ноги) список', source_row, 'legacy', variation_axes, muscle_tags, equipment_tag, description
from sheet_rows
on conflict(canonical_key) do update
set name=excluded.name, muscle_group=excluded.muscle_group,
    exercise_type=excluded.exercise_type, movement_type=excluded.movement_type,
    equipment=excluded.equipment, source_sheet=excluded.source_sheet,
    source_row=excluded.source_row, variation_axes=excluded.variation_axes,
    muscle_tags=excluded.muscle_tags, equipment_tag=excluded.equipment_tag, description=excluded.description,
    status='legacy'
where public.exercises.owner_id is null;

-- Referential integrity: retain the old IDs for already-created programs, scheduled
-- workouts, activity logs, sets, user recents, and shared access grants.
update public.exercises
set status='retired'
where owner_id is null
  and source_sheet is distinct from 'Упражнения (Ноги) список'
  and status <> 'retired';

commit;
